mapper.select:
SELECT * FROM ( select 'erro' as erroOrInfo, null as salerInstCode, null as salerInstName, erro.SALER_ORG_CODE as salerOrgCode, erro.SALER_ORG_NAME as salerOrgName, erro.SALER_ORG_LEVEL as salerOrgLevel, 'A' as dataStatus, erro.DATA_DATE as dataDate, erro.WORKFLOW_ID as workflowId, null as remark, to_char(erro.ERR_MSG) as errMsg from CHB_SALER_INST_ERRODATA erro where 1=1
and erro.SALER_ORG_CODE like concat(concat('%',#{salerOrgCode,jdbcType=VARCHAR}),'%')
and erro.SALER_ORG_LEVEL = #{salerOrgLevel,jdbcType=VARCHAR}
and erro.STATUS = #{status,jdbcType=VARCHAR}
UNION ALL
select 'info' as erroOrInfo, info.SALER_INST_CODE as salerInstCode, info.SALER_INST_NAME as salerInstName, info.SALER_ORG_CODE as salerOrgCode, info.SALER_ORG_NAME as salerOrgName, info.SALER_ORG_LEVEL as salerOrgLevel, info.STATUS as dataStatus, info.DATA_DATE as dataDate, null as workflowId, info.REMARK as remark, null as errMsg from CHB_SALER_INST_INFO info where 1=1
and info.SALER_ORG_CODE like concat(concat('%',#{salerOrgCode,jdbcType=VARCHAR}),'%')
and info.SALER_ORG_LEVEL = #{salerOrgLevel,jdbcType=VARCHAR}
and info.STATUS = #{status,jdbcType=VARCHAR}
) ORDER BY dataStatus DESC

select REGIST_BANK_CODE from CHB_ORG_REGIST_BANK_CODE
where
ORG_CODE = #{orgCode,jdbcType=VARCHAR}
